    // Explicit shims for unrelated file infrastructure referenced by trash.rs.
    pub(crate) fn is_network_share(_path: &Path) -> bool {
        false
    }

    // Retained as an explicit shim for source compatibility with files/mod.rs;
    // current Windows trash paths use the dedicated worker directly.
    #[allow(dead_code)]
    pub(crate) async fn run_blocking<T, F>(function: F) -> Result<T, AppError>
    where
        T: Send + 'static,
        F: FnOnce() -> Result<T, AppError> + Send + 'static,
    {
        match crate::async_runtime::spawn_blocking(function).await {
            Ok(result) => result,
            Err(error) => Err(AppError::WorkerFailed(error.to_string())),
        }
    }

    pub mod file_ops {
        use crate::error::AppError;
        use std::{fs, path::Path};

        pub(crate) fn remove_entry_at(path: &Path) -> Result<(), AppError> {
            let metadata = fs::symlink_metadata(path)?;
            if metadata.is_dir() {
                fs::remove_dir_all(path)?;
            } else if metadata.file_type().is_symlink() {
                fs::remove_file(path).or_else(|_| fs::remove_dir(path))?;
            } else {
                fs::remove_file(path)?;
            }
            Ok(())
        }
    }
}
